// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import {
  ArrowUpLeftIcon,
  LockIcon,
  PauseIcon,
  PictureInPicture2Icon,
  PlayIcon,
  RotateCwIcon,
  XIcon,
} from 'lucide-react'

import { DemoStage, DockHeader, type Build } from '@/app/demos/stage'
import { LogoMark } from '@/app/demos/stage/Logo'

import {
  AUTO_HINT,
  CAPTIONS,
  HOW_TO,
  MENU_ITEM,
  OTHER_TAB,
  PAUSED,
  SHORTCUT,
  VIDEO,
  clock,
} from './script'

const PANEL = 214
const VIDEO_URL = 'https://talks.northwind.dev/watch/side-panel'
const CODE_URL = `https://${OTHER_TAB.host}/northwind/app/src/App.tsx`

const build: Build = ({ tl, q, qa, pos, step, final, move, click, wait, cursorOut }) => {
  const frame = pos('video-frame')
  const dock = pos('pip')
  const docked = {
    x: frame.x - dock.x,
    y: frame.y - dock.y,
    scaleX: frame.w / dock.w,
    scaleY: frame.h / dock.h,
  }

  const keys = () => {
    tl.fromTo(
      q('keys'),
      { opacity: 0, scale: 0.85 },
      { opacity: 1, scale: 1, duration: 0.25, ease: 'back.out(2)', immediateRender: false },
    )
    tl.to(qa('keycap'), { y: 2, duration: 0.08, yoyo: true, repeat: 1, stagger: 0.05 })
    tl.to(q('keys'), { opacity: 0, duration: 0.25 }, '+=0.35')
  }
  const floatOut = (at?: string) => {
    tl.set(q('pip'), { opacity: 1, ...docked }, at)
    tl.to(q('frame-live'), { opacity: 0, duration: 0.2 }, '<')
    tl.to(q('pip'), { x: 0, y: 0, scaleX: 1, scaleY: 1, duration: 0.7, ease: 'power3.inOut' }, '<')
    tl.to(q('frame-note'), { opacity: 1, duration: 0.3 }, '<0.2')
  }
  const floatBack = (at?: string) => {
    tl.to(q('frame-note'), { opacity: 0, duration: 0.2 }, at)
    tl.to(q('pip'), { ...docked, duration: 0.6, ease: 'power3.inOut' }, '<')
    tl.set(q('frame-live'), { opacity: 1 })
    tl.set(q('pip'), { opacity: 0 })
  }
  const showTab = (video: boolean) => {
    tl.to(
      q('tab-video'),
      { backgroundColor: video ? '#0b0b11' : 'rgba(255,255,255,0.03)', duration: 0.15 },
      '<',
    )
    tl.to(
      q('tab-code'),
      { backgroundColor: video ? 'rgba(255,255,255,0.03)' : '#0b0b11', duration: 0.15 },
      '<',
    )
    tl.set(q('url-text'), { text: video ? VIDEO_URL : CODE_URL }, '<')
    tl.to(q('page-code'), { opacity: video ? 0 : 1, duration: 0.2 }, '<')
  }

  step(0)
  move('page-title', { at: 0.3 })
  keys()
  floatOut()
  wait(0.8)

  step(1, '+=0.2')
  keys()
  floatBack('<0.15')
  move('page-desc', { at: '+=0.1' })
  click('page-desc')
  tl.fromTo(
    q('menu'),
    { opacity: 0, scale: 0.96 },
    { opacity: 1, scale: 1, duration: 0.15, immediateRender: false },
    '<',
  )
  move('menu-pip')
  tl.to(q('menu-pip'), { backgroundColor: 'rgba(255,255,255,0.08)', duration: 0.1 })
  click('menu-pip')
  tl.to(q('menu'), { opacity: 0, duration: 0.12 }, '<')
  tl.set(q('menu-pip'), { backgroundColor: 'rgba(255,255,255,0)' })
  floatOut()
  wait(0.4)

  step(2, '+=0.2')
  move('pip-back')
  click('pip-back')
  floatBack('<')
  move('sw-auto')
  click('sw-auto')
  tl.to(q('sw-auto'), { backgroundColor: 'var(--accent)', duration: 0.15 }, '<')
  tl.to(q('sw-auto-knob'), { x: 10, duration: 0.15 }, '<')
  move('tab-code', { at: '+=0.1' })
  click('tab-code')
  showTab(false)
  tl.set(q('pip'), { opacity: 1, x: 0, y: 0, scaleX: 1, scaleY: 1 }, '<')
  tl.fromTo(
    q('pip'),
    { scale: 0.85, autoAlpha: 0 },
    { scale: 1, autoAlpha: 1, duration: 0.45, ease: 'back.out(1.6)', immediateRender: false },
    '<0.1',
  )
  tl.set(q('frame-live'), { opacity: 0 }, '<')
  tl.set(q('frame-note'), { opacity: 1 }, '<')
  move('code-line-4', { at: '+=0.2', ax: 0.6 })
  wait(1.2)
  move('tab-video')
  click('tab-video')
  showTab(true)
  floatBack('<')
  cursorOut('+=0.2')
  final('+=0.1')
  wait(1.2)

  const total = tl.duration()
  const clockProxy = { s: VIDEO.startS }
  const times = qa('v-time')
  const bars = qa('v-bar')
  tl.fromTo(
    clockProxy,
    { s: VIDEO.startS },
    {
      s: VIDEO.startS + total,
      duration: total,
      ease: 'none',
      immediateRender: false,
      onUpdate: () => {
        const label = `${clock(clockProxy.s)} / ${clock(VIDEO.durationS)}`
        for (const el of times) el.textContent = label
        for (const el of bars) el.style.width = `${(clockProxy.s / VIDEO.durationS) * 100}%`
      },
    },
    0,
  )

  tl.set([q('pip'), q('menu'), q('keys'), q('frame-note'), q('page-code')], { opacity: 0 }, 0)
  tl.set(q('pip'), { visibility: 'visible', ...docked }, 0)
  tl.set(q('frame-live'), { opacity: 1 }, 0)
  tl.set(q('sw-auto'), { backgroundColor: 'rgba(255,255,255,0.12)' }, 0)
  tl.set(q('sw-auto-knob'), { x: 0 }, 0)
  tl.set(q('tab-video'), { backgroundColor: '#0b0b11' }, 0)
  tl.set(q('tab-code'), { backgroundColor: 'rgba(255,255,255,0.03)' }, 0)
  tl.set(q('url-text'), { text: VIDEO_URL }, 0)
}

