function CodePage() {
  const lines = [
    ['text-[#c586c0]', 'import', ' { Panel } ', 'from', " './panel'"],
    ['text-[#c586c0]', 'import', ' { useTools } ', 'from', " './tools'"],
    ['', '', '', '', ''],
    ['text-[#569cd6]', 'export default function', ' App() {', '', ''],
    ['text-[#c586c0]', '  const', ' tools = useTools()', '', ''],
    ['text-[#c586c0]', '  return', ' <Panel tools={tools} />', '', ''],
    ['', '}', '', '', ''],
  ]
  return (
    <div
      data-d="page-code"
      className="absolute inset-0 bg-[#1e1e1e] px-3 py-2.5 font-mono text-[8px] leading-[15px] text-[#d4d4d4] opacity-0"
    >
      {lines.map(([tone, keyword, rest, keyword2, rest2], index) => (
        <p key={index} data-d={`code-line-${index}`} className="flex gap-2 whitespace-pre">
          <span className="w-3 text-right text-[#6e7681]">{index + 1}</span>
          <span>
            <span className={tone}>{keyword}</span>
            {rest}
            <span className={tone}>{keyword2}</span>
            <span className="text-[#ce9178]">{rest2}</span>
          </span>
        </p>
      ))}
    </div>
  )
}

